"""Generate one spec file per chapter in _build/spec/. Run: python make_specs.py"""
import glob, pathlib

B = pathlib.Path(__file__).resolve().parent
ROOT = B.parent.parent                      # learnlytica/
SPEC = B / "spec"; SPEC.mkdir(exist_ok=True)
SRC = B.parent / "src"; SRC.mkdir(exist_ok=True)

def one(pattern):
    hits = sorted(glob.glob(str(ROOT / pattern)))
    assert hits, pattern
    return hits[0]

