def write(cid, text):
    (SPEC / f"{cid}.md").write_text(text, encoding="utf-8")

n = 0
for line in DAYS.strip().splitlines():
    d, tags, steps, skills, practice = [x.strip() for x in line.split(" | ", 4)]
    d = int(d); cid = f"D{d:02d}"
    slides = one(f"00 Slides/{d:02d}_*.txt"); tia = one(f"01 Technology in Action/{d:02d}_TIA_*.txt")
    title = pathlib.Path(slides).stem[3:].replace("_", " ")
    steps_txt = "\n".join(f"  {i}. {s.strip()}" for i, s in enumerate(steps.split(" > "), 1))
    write(cid, f"""CHAPTER: {cid}   KIND: DAY
TITLE LINE TO USE: TITLE: Day {d} — {title}   (fix the punctuation of the title so it reads naturally)
OUTPUT PATH: {SRC / (cid + '.md')}

SOURCE FILES (read both in full):
- {slides}
- {tia}

QUIZ TOPICS (section 6: one sub-section and one practice question for each, in this order):
{tags}

HANDS-ON LAB STEPS (section 5):
{steps_txt}

GRADED-LAB SKILLS TO TEACH (section 7):
{skills}

PRACTICE PROBLEM TO SET AND SOLVE (section 7):
{practice}
""")
    n += 1

for num, name, day in PROJECTS:
    cid = f"P{num}"
    src = one(f"02 Projects/Project {num} - *.txt")
    write(cid, f"""CHAPTER: {cid}   KIND: PROJECT
TITLE LINE TO USE: TITLE: Project {num} — {name}
OUTPUT PATH: {SRC / (cid + '.md')}

SOURCE FILE (read in full): {src}
This is milestone project {num} of 6, set on course day {day}. Its last part, "Part G - Your challenges", is five assessed tasks, each with a "Done when" acceptance test.

{PROJECT_SECTIONS}
""")
    n += 1

for cid, (title, sources, body) in EXTRA.items():
    srcs = "\n".join(f"- {ROOT / s}" for s in sources) or "(none)"
    write(cid, f"""CHAPTER: {cid}   KIND: {'FOUNDATION' if cid[0] == 'F' else 'OFFER'}
TITLE LINE TO USE: TITLE: {title}
OUTPUT PATH: {SRC / (cid + '.md')}

SOURCE FILES:
{srcs}

{body}
""")
    n += 1
print(n, "specs written to", SPEC)
